1	package input_test
2	
3	// These cases call the two shared entries directly, without any HTTP
4	// machinery: they pin what a non-HTTP caller of ParseRegistration and
5	// ParseQuery receives — an exact service.RegisterInput / service.Query on
6	// success, or ErrInvalidInput together with a zero result. The HTTP-side
7	// mirror lives in internal/api.
8	
9	import (
10		"errors"
11		"io"
12		"reflect"
13		"strings"
14		"testing"
15	
16		"github.com/Bob-xisuke/orb-registry-catalog/internal/input"
17		"github.com/Bob-xisuke/orb-registry-catalog/internal/service"
18	)
19	
20	const (
21		digestA = "sha256:" + "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"
22		digestB = "sha256:" + "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb"
23	)
24	
25	// validBody is a registration every field of which is legal.
26	func validBody(repo, digest, tag string) string {
27		return `{"repository":"` + repo + `","digest":"` + digest + `","tag":"` + tag +
28			`","signature_verified":true,"retention_days":30,"size_bytes":1024}`
29	}
30	
31	// failingReader returns err on every Read, optionally delivering prefix
32	// bytes first so both immediate and mid-body failures can be exercised.
33	type failingReader struct {
34		prefix []byte
35		err    error
36	}
37	
38	func (f *failingReader) Read(p []byte) (int, error) {
39		if len(f.prefix) > 0 {
40			n := copy(p, f.prefix)
41			f.prefix = f.prefix[n:]
42			return n, nil
43		}
44		return 0, f.err
45	}
46	
47	// TestParseRegistrationSuccessExactFields proves the success path returns a
48	// fully populated service.RegisterInput: trim normalization for repository
49	// and tag, the digest kept verbatim, and the two integers kept as exact
50	// int64 values. Unknown fields never enter the result.
51	func TestParseRegistrationSuccessExactFields(t *testing.T) {
52		body := `{"repository":"  team/app  ","digest":"` + digestA + `","tag":"  latest  ",` +
53			`"signature_verified":false,"retention_days":1,"size_bytes":0,"extra":"ignored"}`
54		got, err := input.ParseRegistration(strings.NewReader(body))
55		if err != nil {
56			t.Fatalf("ParseRegistration: %v", err)
57		}
58		want := service.RegisterInput{
59			Repository:        "team/app",
60			Digest:            digestA,
61			Tag:               "latest",
62			SignatureVerified: false,
63			RetentionDays:     1,
64			SizeBytes:         0,
65		}
66		if !reflect.DeepEqual(got, want) {
67			t.Fatalf("RegisterInput = %+v, want %+v", got, want)
68		}
69	}
70	
71	// TestParseRegistrationExactInt64 pins the precise integer representation:
72	// 2^53+1 (not representable as float64) and max int64 survive exactly,
73	// retention accepts its 3650 maximum, and the fractional/exponential/string
74	// neighbors are all refused.
75	func TestParseRegistrationExactInt64(t *testing.T) {
76		cases := map[string]struct {
77			retention, size string
78			wantRetention   int64
79			wantSize        int64
80		}{
81			"size 2^53+1":    {"1", "9007199254740993", 1, 9007199254740993},
82			"size max int64": {"3650", "9223372036854775807", 3650, 9223372036854775807},
83			"retention 3650": {"3650", "1", 3650, 1},
84			"false and zero": {"1", "0", 1, 0},
85		}
86		for name, tc := range cases {
87			t.Run(name, func(t *testing.T) {
88				body := `{"repository":"team/exact","digest":"` + digestA + `","tag":"t",` +
89					`"signature_verified":true,"retention_days":` + tc.retention +
90					`,"size_bytes":` + tc.size + `}`
91				got, err := input.ParseRegistration(strings.NewReader(body))
92				if err != nil {
93					t.Fatalf("ParseRegistration: %v", err)
94				}
95				if got.RetentionDays != tc.wantRetention || got.SizeBytes != tc.wantSize {
96					t.Fatalf("integers = (%d, %d), want (%d, %d)",
97						got.RetentionDays, got.SizeBytes, tc.wantRetention, tc.wantSize)
98				}
99			})
100		}
101	
102		rejected := map[string]string{
103			"size overflows int64": "9223372036854775808",
104			"size string digits":   `"1024"`,
105			"size fractional":      "1024.0",
106			"size exponential":     "1e3",
107			"size boolean":         "true",
108		}
109		for name, raw := range rejected {
110			t.Run(name, func(t *testing.T) {
111				body := `{"repository":"team/exact","digest":"` + digestA + `","tag":"t",` +
112					`"signature_verified":true,"retention_days":30,"size_bytes":` + raw + `}`
113				if _, err := input.ParseRegistration(strings.NewReader(body)); !errors.Is(err, input.ErrInvalidInput) {
114					t.Fatalf("size %s error = %v, want ErrInvalidInput", raw, err)
115				}
116			})
117		}
118		for name, raw := range map[string]string{
119			"retention overflows":   "9223372036854775808",
120			"retention fractional":  "30.0",
121			"retention exponential": "3e1",
122			"retention string":      `"30"`,
123		} {
124			t.Run(name, func(t *testing.T) {
125				body := `{"repository":"team/exact","digest":"` + digestA + `","tag":"t",` +
126					`"signature_verified":true,"retention_days":` + raw + `,"size_bytes":1}`
127				if _, err := input.ParseRegistration(strings.NewReader(body)); !errors.Is(err, input.ErrInvalidInput) {
128					t.Fatalf("retention %s error = %v, want ErrInvalidInput", raw, err)
129				}
130			})
131		}
132	}
133	
134	// TestParseRegistrationInvalidReturnsZeroAndSentinel enumerates every
135	// rejection class and pins both halves of the contract: errors.Is recognizes
136	// ErrInvalidInput and the returned input is the zero value.
137	func TestParseRegistrationInvalidReturnsZeroAndSentinel(t *testing.T) {
138		cases := map[string]string{
139			"empty body":            ``,
140			"json array":            `[{"repository":"team/app"}]`,
141			"json scalar":           `"text"`,
142			"json number":           `42`,
143			"json null":             `null`,
144			"trailing object":       validBody("team/app", digestA, "latest") + ` {}`,
145			"trailing token":        validBody("team/app", digestA, "latest") + ` garbage`,
146			"malformed json":        `{"repository":`,
147			"double comma":          `{"repository":"team/app",,"digest":"` + digestA + `"}`,
148			"missing repository":    `{"digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
149			"missing digest":        `{"repository":"team/app","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
150			"missing tag":           `{"repository":"team/app","digest":"` + digestA + `","signature_verified":true,"retention_days":30,"size_bytes":1}`,
151			"missing signature":     `{"repository":"team/app","digest":"` + digestA + `","tag":"t","retention_days":30,"size_bytes":1}`,
152			"missing retention":     `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"size_bytes":1}`,
153			"missing size":          `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30}`,
154			"null repository":       `{"repository":null,"digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
155			"null tag":              `{"repository":"team/app","digest":"` + digestA + `","tag":null,"signature_verified":true,"retention_days":30,"size_bytes":1}`,
156			"null signature":        `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":null,"retention_days":30,"size_bytes":1}`,
157			"null retention":        `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":null,"size_bytes":1}`,
158			"null size":             `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":null}`,
159			"blank repository":      `{"repository":"   ","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
160			"blank tag":             `{"repository":"team/app","digest":"` + digestA + `","tag":"  ","signature_verified":true,"retention_days":30,"size_bytes":1}`,
161			"repository wrong type": `{"repository":7,"digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
162			"tag wrong type":        `{"repository":"team/app","digest":"` + digestA + `","tag":7,"signature_verified":true,"retention_days":30,"size_bytes":1}`,
163			"digest wrong type":     `{"repository":"team/app","digest":7,"tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
164			"digest wrong prefix":   `{"repository":"team/app","digest":"sha512:` + strings.Repeat("a", 64) + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
165			"digest uppercase hex":  `{"repository":"team/app","digest":"sha256:` + strings.Repeat("A", 64) + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
166			"digest too short":      `{"repository":"team/app","digest":"sha256:` + strings.Repeat("a", 63) + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
167			"digest leading space":  `{"repository":"team/app","digest":" ` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
168			"signature string":      `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":"true","retention_days":30,"size_bytes":1}`,
169			"retention zero":        `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":0,"size_bytes":1}`,
170			"retention too large":   `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":3651,"size_bytes":1}`,
171			"size negative":         `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":-1}`,
172		}
173		for name, body := range cases {
174			t.Run(name, func(t *testing.T) {
175				got, err := input.ParseRegistration(strings.NewReader(body))
176				if !errors.Is(err, input.ErrInvalidInput) {
177					t.Fatalf("error = %v, want ErrInvalidInput", err)
178				}
179				if got != (service.RegisterInput{}) {
180					t.Fatalf("result = %+v, want zero RegisterInput", got)
181				}
182			})
183		}
184	}
185	
186	// TestParseRegistrationReadFailure proves a reader failure is the same
187	// published failure as a syntax error: ErrInvalidInput plus a zero result,
188	// whether the failure arrives before any byte or mid-body.
189	func TestParseRegistrationReadFailure(t *testing.T) {
190		boom := errors.New("read boom")
191		for name, reader := range map[string]io.Reader{
192			"immediate": &failingReader{err: boom},
193			"mid body":  &failingReader{prefix: []byte(`{"repository":"team/app"`), err: boom},
194		} {
195			t.Run(name, func(t *testing.T) {
196				got, err := input.ParseRegistration(reader)
197				if !errors.Is(err, input.ErrInvalidInput) {
198					t.Fatalf("error = %v, want ErrInvalidInput", err)
199				}
200				if got != (service.RegisterInput{}) {
201					t.Fatalf("result = %+v, want zero RegisterInput", got)
202				}
203			})
204		}
205	
206		// A nil reader is the same failure class.
207		if got, err := input.ParseRegistration(nil); !errors.Is(err, input.ErrInvalidInput) || got != (service.RegisterInput{}) {
208			t.Fatalf("nil reader = (%+v, %v), want zero result and ErrInvalidInput", got, err)
209		}
210	}
211	
212	// TestParseRegistrationDuplicateKeysLastValueWins proves the last
213	// occurrence of every key is the only one decoded: a legal last value wins
214	// over a decoy or illegal earlier one, while an illegal last value fails
215	// even though every earlier value was legal.
216	func TestParseRegistrationDuplicateKeysLastValueWins(t *testing.T) {
217		body := `{"repository":"team/decoy","repository":"team/dup",` +
218			`"digest":"` + digestB + `","digest":"` + digestA + `",` +
219			`"tag":"decoy","tag":"release",` +
220			`"signature_verified":"yes","signature_verified":true,` +
221			`"retention_days":null,"retention_days":30,` +
222			`"size_bytes":"1024","size_bytes":9007199254740993}`
223		got, err := input.ParseRegistration(strings.NewReader(body))
224		if err != nil {
225			t.Fatalf("legal-last ParseRegistration: %v", err)
226		}
227		want := service.RegisterInput{
228			Repository: "team/dup", Digest: digestA, Tag: "release",
229			SignatureVerified: true, RetentionDays: 30, SizeBytes: 9007199254740993,
230		}
231		if !reflect.DeepEqual(got, want) {
232			t.Fatalf("last-wins result = %+v, want %+v", got, want)
233		}
234	
235		// Normalization applies to the last value: an earlier untrimmed value
236		// loses to a trimmed last one.
237		trimmed := `{"repository":"team/decoy","repository":"  team/trim  ","digest":"` + digestA +
238			`","tag":"first","tag":"  release  ","signature_verified":false,"retention_days":1,"size_bytes":0}`
239		got, err = input.ParseRegistration(strings.NewReader(trimmed))
240		if err != nil {
241			t.Fatalf("trim-last ParseRegistration: %v", err)
242		}
243		if got.Repository != "team/trim" || got.Tag != "release" {
244			t.Fatalf("last values not trimmed: %+v", got)
245		}
246	
247		// Illegal last values: the earlier legal occurrence cannot rescue them.
248		for name, tail := range map[string]string{
249			"repository null":  `{"repository":"team/app","repository":null,"digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1}`,
250			"tag blank":        `{"repository":"team/app","digest":"` + digestA + `","tag":"ok","tag":"  ","signature_verified":true,"retention_days":30,"size_bytes":1}`,
251			"signature string": `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"signature_verified":"yes","retention_days":30,"size_bytes":1}`,
252			"retention null":   `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"retention_days":null,"size_bytes":1}`,
253			"size fractional":  `{"repository":"team/app","digest":"` + digestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1,"size_bytes":1.5}`,
254		} {
255			t.Run(name, func(t *testing.T) {
256				got, err := input.ParseRegistration(strings.NewReader(tail))
257				if !errors.Is(err, input.ErrInvalidInput) || got != (service.RegisterInput{}) {
258					t.Fatalf("illegal last = (%+v, %v), want zero result and ErrInvalidInput", got, err)
259				}
260			})
261		}
262	}
263	
264	// TestParseRegistrationEscapedKeyNames proves key matching runs on the
265	// decoded name, and plain/escaped spellings of the same name collide with
266	// document order — the same last-wins rule as ordinary duplicates.
267	func TestParseRegistrationEscapedKeyNames(t *testing.T) {
268		body := `{` +
269			`"\u0072epository":"team/uni",` +
270			`"\u0064igest":"` + digestA + `",` +
271			`"\u0074ag":"release",` +
272			`"signature_\u0076erified":true,` +
273			`"retention_\u0064ays":30,` +
274			`"size_\u0062ytes":1024}`
275		if _, err := input.ParseRegistration(strings.NewReader(body)); err != nil {
276			t.Fatalf("escaped keys rejected: %v", err)
277		}
278	
279		// A literal backslash-u escape, built so the test file itself stays
280		// ASCII: decoded, "\u0074ag" is the same key as "tag".
281		literalEsc := "{\"repository\":\"team/uni2\",\"digest\":\"" + digestB + "\"," +
282			"\"tag\":\"plain\",\"\\u0074ag\":\"escaped\",\"signature_verified\":true,\"retention_days\":30,\"size_bytes\":1}"
283		got, err := input.ParseRegistration(strings.NewReader(literalEsc))
284		if err != nil {
285			t.Fatalf("literal \\u escape: %v", err)
286		}
287		if got.Tag != "escaped" {
288			t.Fatalf("escaped spelling last: tag = %q, want escaped", got.Tag)
289		}
290	
291		// A merely similar unknown key never stands in for the required one.
292		missing := `{"repo":"team/uni3","digest":"` + digestA + `","tag":"t",` +
293			`"signature_verified":true,"retention_days":30,"size_bytes":1}`
294		if _, err := input.ParseRegistration(strings.NewReader(missing)); !errors.Is(err, input.ErrInvalidInput) {
295			t.Fatalf("unknown key satisfied a required one: %v", err)
296		}
297	}
298	
299	// TestParseQueryModesExactQueries pins the three dispatched shapes and the
300	// normalization boundary: repository/tag trimmed after decoding, the digest
301	// kept verbatim.
302	func TestParseQueryModesExactQueries(t *testing.T) {
303		cases := map[string]struct {
304			raw  string
305			want service.Query
306		}{
307			"repository list": {
308				"repository=++team/app++",
309				service.Query{Kind: service.QueryByRepository, Repository: "team/app"},
310			},
311			"by tag trimmed": {
312				"repository=team/app&tag=+release+",
313				service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "release"},
314			},
315			"by tag with literal plus": {
316				"repository=team/app&tag=a%2Bb",
317				service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "a+b"},
318			},
319			"by tag with decoded space": {
320				"repository=team/app&tag=a+b",
321				service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "a b"},
322			},
323			"by digest untrimmed": {
324				"repository=team/app&digest=" + digestA,
325				service.Query{Kind: service.QueryByDigest, Repository: "team/app", Digest: digestA},
326			},
327			"unknown parameters ignored": {
328				"repository=team/app&unknown=1&frob=&tag=release",
329				service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "release"},
330			},
331		}
332		for name, tc := range cases {
333			t.Run(name, func(t *testing.T) {
334				got, err := input.ParseQuery(tc.raw)
335				if err != nil {
336					t.Fatalf("ParseQuery(%q): %v", tc.raw, err)
337				}
338				if !reflect.DeepEqual(got, tc.want) {
339					t.Fatalf("ParseQuery(%q) = %+v, want %+v", tc.raw, got, tc.want)
340				}
341			})
342		}
343	}
344	
345	// TestParseQueryFirstValueWins proves later occurrences of any recognized
346	// parameter never participate: neither retargeting a legal first value nor
347	// rescuing an illegal one.
348	func TestParseQueryFirstValueWins(t *testing.T) {
349		want := service.Query{Kind: service.QueryByTag, Repository: "team/app", Tag: "alpha"}
350		for _, raw := range []string{
351			"repository=team/app&tag=alpha&tag=beta",
352			"repository=team/app&tag=alpha&tag=",
353			"repository=team/app&tag=alpha&tag=sha256:xyz",
354			"repository=team/app&repository=other/repo&tag=alpha",
355		} {
356			got, err := input.ParseQuery(raw)
357			if err != nil {
358				t.Fatalf("ParseQuery(%q): %v", raw, err)
359			}
360			if !reflect.DeepEqual(got, want) {
361				t.Fatalf("ParseQuery(%q) = %+v, want %+v", raw, got, want)
362			}
363		}
364	
365		// An illegal first value is rejected even when every later value is legal.
366		for _, raw := range []string{
367			"repository=&repository=team/app&tag=release",
368			"repository=%20%20&repository=team/app&tag=release",
369			"repository&repository=team/app&tag=release",
370			"repository=team/app&tag=&tag=release",
371			"repository=team/app&tag=%20%20&tag=release",
372			"repository=team/app&tag&tag=release",
373			"repository=team/app&digest=sha256:xyz&digest=" + digestA,
374			"repository=team/app&digest&digest=" + digestA,
375			"repository=team/app&digest=+" + digestA + "&digest=" + digestA,
376		} {
377			if _, err := input.ParseQuery(raw); !errors.Is(err, input.ErrInvalidInput) {
378				t.Fatalf("ParseQuery(%q) error = %v, want ErrInvalidInput", raw, err)
379			}
380		}
381	}
382	
383	// TestParseQueryNamesDecodedCaseSensitive proves names match after
384	// percent-decoding but stay case sensitive, and that the raw string is used
385	// verbatim — a leading '?' is not stripped.
386	func TestParseQueryNamesDecodedCaseSensitive(t *testing.T) {
387		// Decoded-name collisions obey the same first-value ordering.
388		got, err := input.ParseQuery("repository=team/app&%74ag=release")
389		if err != nil {
390			t.Fatalf("escaped tag name: %v", err)
391		}
392		if got.Kind != service.QueryByTag || got.Tag != "release" {
393			t.Fatalf("%%74ag did not decode to tag: %+v", got)
394		}
395		if _, err := input.ParseQuery("repository=team/app&%64igest=" + digestB); err != nil {
396			t.Fatalf("escaped digest name: %v", err)
397		}
398	
399		// A cased spelling is unknown: absent both selectors, the request is a
400		// legal repository list, not a tag query.
401		list, err := input.ParseQuery("repository=team/app&Tag=release&TAG=x")
402		if err != nil {
403			t.Fatalf("cased names: %v", err)
404		}
405		if list.Kind != service.QueryByRepository {
406			t.Fatalf("Tag= was treated as the tag query: %+v", list)
407		}
408	
409		// A cased repository spelling cannot satisfy the required name.
410		if _, err := input.ParseQuery("Repository=team/app&tag=release"); !errors.Is(err, input.ErrInvalidInput) {
411			t.Fatalf("Repository= error = %v, want ErrInvalidInput", err)
412		}
413	
414		// The contract takes the string without its '?'; passing one makes the
415		// leading '?' part of the first key name, so repository is missing.
416		if _, err := input.ParseQuery("?repository=team/app"); !errors.Is(err, input.ErrInvalidInput) {
417			t.Fatalf("leading '?' error = %v, want ErrInvalidInput", err)
418		}
419	}
420	
421	// TestParseQueryInvalidReturnsZeroAndSentinel enumerates the invalid query
422	// shapes and pins the zero result alongside the sentinel, including the
423	// both-selectors-present rule in either order.
424	func TestParseQueryInvalidReturnsZeroAndSentinel(t *testing.T) {
425		for _, raw := range []string{
426			"",
427			"unknown=1",
428			"repository=",
429			"repository=%20%20",
430			"repository&tag=release",
431			"tag=release",
432			"repository=team/app&tag=",
433			"repository=team/app&tag",
434			"repository=team/app&tag=%20%20",
435			"repository=team/app&digest=",
436			"repository=team/app&digest",
437			"repository=team/app&digest=sha256:xyz",
438			"repository=team/app&digest=" + digestA + "+",
439			"repository=team/app&digest=%20" + digestA,
440			"repository=team/app&tag=release&digest=" + digestA,
441			"repository=team/app&digest=" + digestA + "&tag=release",
442			"repository=team/app&tag=&digest=",
443		} {
444			got, err := input.ParseQuery(raw)
445			if !errors.Is(err, input.ErrInvalidInput) {
446				t.Fatalf("ParseQuery(%q) error = %v, want ErrInvalidInput", raw, err)
447			}
448			if got != (service.Query{}) {
449				t.Fatalf("ParseQuery(%q) = %+v, want zero Query", raw, got)
450			}
451		}
452	}
453	
454	// TestParseQuerySkippedPairsStillSelectMode proves the two "pair ignored"
455	// cases — an undecodable escape and an unescaped semicolon segment — leave
456	// the remaining pairs in control of the mode, exactly as url.ParseQuery
457	// orders them. A skipped recognized parameter is simply absent.
458	func TestParseQuerySkippedPairsStillSelectMode(t *testing.T) {
459		// Undecodable pairs vanish: the bad tag is absent, so this is a list.
460		got, err := input.ParseQuery("repository=team/app&tag=%zz")
461		if err != nil {
462			t.Fatalf("bad-escape pair: %v", err)
463		}
464		if got.Kind != service.QueryByRepository || got.Repository != "team/app" {
465			t.Fatalf("bad-escape pair not skipped: %+v", got)
466		}
467	
468		// A decodable pair after the bad one still counts; first-value ordering
469		// holds across the gap.
470		first := "repository=team/app&tag=%zz&tag=release"
471		if got, err := input.ParseQuery(first); err != nil || got.Kind != service.QueryByTag || got.Tag != "release" {
472			t.Fatalf("ParseQuery(%q) = (%+v, %v), want a tag query for release", first, got, err)
473		}
474	
475		// An unescaped ';' invalidates only the segment carrying it: the tag
476		// segment is dropped wholesale, leaving repository alone as a legal list.
477		tagSegment := "repository=team/app&tag=release;evil=1"
478		got, err = input.ParseQuery(tagSegment)
479		if err != nil {
480			t.Fatalf("ParseQuery(%q): %v", tagSegment, err)
481		}
482		if got.Kind != service.QueryByRepository || got.Repository != "team/app" {
483			t.Fatalf("semicolon tag segment not skipped: %+v", got)
484		}
485	
486		// A semicolon in the repository segment drops the repository itself, so
487		// the same input is now the missing-repository failure.
488		if _, err := input.ParseQuery("repository=team/app;a=b&tag=release"); !errors.Is(err, input.ErrInvalidInput) {
489			t.Fatalf("semicolon repository segment error = %v, want ErrInvalidInput", err)
490		}
491	
492		// The selector segment carrying the ';' is dropped while a clean selector
493		// in a later segment survives and picks the mode by itself.
494		tagSurvives, err := input.ParseQuery("repository=team/app&digest=" + digestA + ";x=1&tag=release")
495		if err != nil {
496			t.Fatalf("semicolon digest segment: %v", err)
497		}
498		if tagSurvives.Kind != service.QueryByTag || tagSurvives.Tag != "release" {
499			t.Fatalf("valid pair after semicolon segment lost: %+v", tagSurvives)
500		}
501	
502		// A properly percent-encoded semicolon is an ordinary value character:
503		// the segment is not skipped.
504		encoded, err := input.ParseQuery("repository=team/app&tag=a%3Bb")
505		if err != nil {
506			t.Fatalf("encoded semicolon: %v", err)
507		}
508		if encoded.Tag != "a;b" {
509			t.Fatalf("%%3B decoded tag = %q, want a;b", encoded.Tag)
510		}
511	}
512	
513	// TestParseQueryPlusAndPercent2BReachDifferentTags pins the decode rule the
514	// tag side normalization is built on.
515	func TestParseQueryPlusAndPercent2BReachDifferentTags(t *testing.T) {
516		space, err := input.ParseQuery("repository=team/app&tag=a+b")
517		if err != nil {
518			t.Fatalf("plus: %v", err)
519		}
520		space2, err := input.ParseQuery("repository=team/app&tag=a%20b")
521		if err != nil {
522			t.Fatalf("percent-20: %v", err)
523		}
524		plus, err := input.ParseQuery("repository=team/app&tag=a%2Bb")
525		if err != nil {
526			t.Fatalf("percent-2B: %v", err)
527		}
528		if space.Tag != "a b" || space2.Tag != "a b" {
529			t.Fatalf("'+' / %%20 decoded as %q / %q, want a b both", space.Tag, space2.Tag)
530		}
531		if plus.Tag != "a+b" {
532			t.Fatalf("%%2B decoded as %q, want a+b", plus.Tag)
533		}
534		if reflect.DeepEqual(space, plus) {
535			t.Fatalf("space and plus queries collapsed to the same value: %+v", plus)
536		}
537	}
538

