97			return s.records[idx], nil
98		}
99		return service.Record{}, service.ErrRecordNotFound
100	}
101	
102	func (s *captureStore) RecordByTag(repository, tag string) (service.Record, error) {
103		s.readCalls++
104		s.lastQuery = service.Query{Kind: service.QueryByTag, Repository: repository, Tag: tag}
105		if s.fault != nil {
106			return service.Record{}, s.fault
107		}
108		digest, ok := s.tags[repository][tag]
109		if !ok {
110			return service.Record{}, service.ErrRecordNotFound
111		}
112		return s.records[s.byID[captureID(repository, digest)]], nil
113	}
