115	// recordMatchesInput compares the six caller-owned fields; pushed_at is
116	// service-generated and never part of the parsed input.
117	func recordMatchesInput(t *testing.T, r service.Record, in service.RegisterInput) {
118		t.Helper()
119		got := service.RegisterInput{
120			Repository:        r.Repository,
121			Digest:            r.Digest,
122			Tag:               r.Tag,
123			SignatureVerified: r.SignatureVerified,
124			RetentionDays:     r.RetentionDays,
125			SizeBytes:         r.SizeBytes,
126		}
127		if got != in {
128			t.Fatalf("store received %+v, want direct ParseRegistration result %+v", got, in)
129		}
130		if r.PushedAt == "" {
131			t.Fatalf("service generated no pushed_at; the input entry must not")
132		}
133	}
