139	// TestDirectAndHTTPRegistrationShareOneEntry drives every registration
140	// shape through both entries and pins their identity: the HTTP handler
141	// passes the direct ParseRegistration result to the service, rejections are
142	// the shared sentinel on one side and the published 400 on the other, and a
143	// rejected body never reaches storage.
144	func TestDirectAndHTTPRegistrationShareOneEntry(t *testing.T) {
145		valid := map[string]string{
146			"plain":             registration("registry-demo/cap", testDigestA, "release", true, regRetention, regSizeA),
147			"trimmed and zeros": `{"repository":"  registry-demo/cap  ","digest":"` + testDigestB + `","tag":"  zero  ","signature_verified":false,"retention_days":1,"size_bytes":0,"extra":"ignored"}`,
148			"exact 2^53+1":      registration("registry-demo/cap", testDigestC, "big", true, 1, 9007199254740993),
149			"exact max int64":   registration("registry-demo/cap", testDigestD, "max", true, 3650, 9223372036854775807),
150			"duplicate keys": `{"repository":"registry-demo/decoy","repository":"registry-demo/cap",` +
151				`"digest":"` + testDigestB + `","digest":"` + testDigestA + `",` +
152				`"tag":"decoy","tag":"release","signature_verified":"x","signature_verified":true,` +
153				`"retention_days":null,"retention_days":30,"size_bytes":"1","size_bytes":1024}`,
154			"unicode escaped keys": `{` +
155				`"\u0072epository":"registry-demo/cap",` +
156				`"\u0064igest":"` + testDigestE + `",` +
157				`"\u0074ag":"escaped",` +
158				`"signature_\u0076erified":true,` +
159				`"retention_\u0064ays":30,` +
160				`"size_\u0062ytes":7}`,
161		}
162		for name, body := range valid {
163			t.Run(name, func(t *testing.T) {
164				st := newCaptureStore()
165				router := newCaptureRouter(st)
166	
167				direct, err := input.ParseRegistration(strings.NewReader(body))
168				if err != nil {
169					t.Fatalf("direct ParseRegistration: %v", err)
170				}
171				recorder := postArtifact(t, router, body)
172				if recorder.Code != http.StatusCreated {
173					t.Fatalf("HTTP status = %d, want 201 (%s)", recorder.Code, recorder.Body)
174				}
175				if st.regCalls != 1 {
176					t.Fatalf("store Register calls = %d, want exactly 1", st.regCalls)
177				}
178				recordMatchesInput(t, st.lastRecord, direct)
179	
180				// The identical retry keeps 201, reaches storage with the very
181				// same parsed input, and changes neither record nor tag target.
182				retry := postArtifact(t, router, body)
183				if retry.Code != http.StatusCreated {
184					t.Fatalf("retry status = %d, want 201 (%s)", retry.Code, retry.Body)
185				}
186				recordMatchesInput(t, st.lastRecord, direct)
187				if len(st.records) != 1 {
188					t.Fatalf("identical retry wrote a record: now %d", len(st.records))
189				}
190			})
191		}
192	
193		invalid := map[string]string{
194			"malformed json":      `{"repository":`,
195			"json array":          `["repository"]`,
196			"json null":           `null`,
197			"trailing content":    valid["plain"] + ` {}`,
198			"missing field":       registrationWithField("size_bytes", ""),
199			"null field":          registrationWithField("signature_verified", "null"),
200			"blank after trim":    registrationWithField("tag", `"  "`),
201			"duplicate last null": `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":4,"size_bytes":null}`,
202			"fractional integer":  `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":1.5}`,
203			"exponential integer": `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":3e1,"size_bytes":1}`,
204			"string integer":      `{"repository":"registry-demo/cap","digest":"` + testDigestA + `","tag":"t","signature_verified":true,"retention_days":"30","size_bytes":1}`,
205			"int64 overflow": `{"repository":"registry-demo/cap","digest":"` + testDigestA +
206				`","tag":"t","signature_verified":true,"retention_days":30,"size_bytes":9223372036854775808}`,
207			"retention out of range": registration("registry-demo/cap", testDigestA, "t", true, 3651, 1),
208		}
209		for name, body := range invalid {
210			t.Run(name, func(t *testing.T) {
211				st := newCaptureStore()
212				router := newCaptureRouter(st)
213	
214				direct, err := input.ParseRegistration(strings.NewReader(body))
215				if !errors.Is(err, input.ErrInvalidInput) {
216					t.Fatalf("direct error = %v, want ErrInvalidInput", err)
217				}
218				if direct != (service.RegisterInput{}) {
219					t.Fatalf("direct result = %+v, want zero", direct)
220				}
221				assertErrorResponse(t, postArtifact(t, router, body),
222					http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
223				if st.regCalls != 0 {
224					t.Fatalf("rejected body reached storage %d times", st.regCalls)
225				}
226			})
227		}
228	}
