230	// TestDirectAndHTTPRegistrationReadFailure pins the reader-failure row on
231	// both entries with the same failing stream.
232	func TestDirectAndHTTPRegistrationReadFailure(t *testing.T) {
233		newFail := func() io.Reader {
234			return &registrationFailReader{prefix: []byte(`{"repository":"x"`), err: errors.New("read boom")}
235		}
236		st := newCaptureStore()
237		router := newCaptureRouter(st)
