253	// registrationFailReader delivers prefix once, then err on every Read.
254	type registrationFailReader struct {
255		prefix []byte
256		err    error
257	}
258	
259	func (r *registrationFailReader) Read(p []byte) (int, error) {
260		if len(r.prefix) > 0 {
261			n := copy(p, r.prefix)
262			r.prefix = r.prefix[n:]
263			return n, nil
264		}
265		return 0, r.err
266	}
