268	// TestDirectAndHTTPQueryShareOneEntry drives each query shape through both
269	// entries: the dispatched store call reconstructs exactly the service.Query
270	// the direct call returned; invalid rows are the sentinel plus 400 with no
271	// storage call.
272	func TestDirectAndHTTPQueryShareOneEntry(t *testing.T) {
273		st := newCaptureStore()
274		router := newCaptureRouter(st)
275		const repo = "registry-demo/qcap"
276		// Seed so every legal selector resolves: alpha, beta, a space tag and a
277		// plus tag.
278		mustRegister(t, router, repo, testDigestA, "alpha")
279		mustRegister(t, router, repo, testDigestB, "beta")
280		postArtifact(t, router, registration(repo, testDigestD, "a b", true, regRetention, regSizeA))
281		postArtifact(t, router, registration(repo, testDigestE, "a+b", true, regRetention, regSizeA))
282	
283		cases := map[string]string{
284			"repository list":           "repository=" + repo,
285			"repository padded":         "repository=++" + repo + "++",
286			"tag first value":           "repository=" + repo + "&tag=alpha&tag=beta",
287			"tag later illegal ignored": "repository=" + repo + "&tag=alpha&tag=",
288			"tag later missing ignored": "repository=" + repo + "&tag=beta&tag=missing",
289			"digest first value":        "repository=" + repo + "&digest=" + testDigestA + "&digest=" + testDigestB,
290			"digest later malformed":    "repository=" + repo + "&digest=" + testDigestA + "&digest=sha256:xyz",
291			"plus decodes to space":     "repository=" + repo + "&tag=a+b",
292			"percent-20 decodes space":  "repository=" + repo + "&tag=a%20b",
293			"percent-2B decodes plus":   "repository=" + repo + "&tag=a%2Bb",
294			"escaped tag name":          "repository=" + repo + "&%74ag=alpha",
295			"cased name is unknown":     "repository=" + repo + "&Tag=alpha",
296			"unknown repeats ignored":   "repository=" + repo + "&tag=alpha&frob=1&frob=2",
297			"undecodable pair skipped":  "repository=" + repo + "&tag=%zz",
298			"bad pair before good tag":  "repository=" + repo + "&tag=%zz&tag=alpha",
299			"semicolon segment skipped": "repository=" + repo + "&tag=alpha;evil=1",
300			"selector after semicolon":  "repository=" + repo + "&digest=" + testDigestA + ";x=1&tag=alpha",
301		}
302		for name, raw := range cases {
303			t.Run(name, func(t *testing.T) {
304				direct, err := input.ParseQuery(raw)
305				if err != nil {
306					t.Fatalf("direct ParseQuery(%q): %v", raw, err)
307				}
308				recorder := getArtifacts(t, router, raw)
309				if recorder.Code == http.StatusBadRequest {
310					t.Fatalf("HTTP 400 for a query direct parsing accepted: %s", recorder.Body)
311				}
312				if !reflect.DeepEqual(st.lastQuery, direct) {
313					t.Fatalf("dispatched query = %+v, want direct result %+v", st.lastQuery, direct)
314				}
315			})
316		}
317	
318		// A literal %3B in a tag value reaches storage decoded (no segment is
319		// skipped); it simply matches no tag, which is the 404 path.
320		raw := "repository=" + repo + "&tag=a%3Bb"
321		direct, err := input.ParseQuery(raw)
322		if err != nil {
323			t.Fatalf("direct %%3B query: %v", err)
324		}
325		if direct.Tag != "a;b" {
326			t.Fatalf("%%3B tag = %q, want a;b", direct.Tag)
327		}
328		assertErrorResponse(t, getArtifacts(t, router, raw), http.StatusNotFound, codeNotFound, msgNotFound)
329		if !reflect.DeepEqual(st.lastQuery, direct) {
330			t.Fatalf("%%3B dispatched query = %+v, want %+v", st.lastQuery, direct)
331		}
332	
333		invalid := []string{
334			"",
335			"repository=&tag=alpha",
336			"repository=%20%20",
337			"repository&tag=alpha",
338			"repository=" + repo + "&tag=",
339			"repository=" + repo + "&tag=%20%20",
340			"repository=" + repo + "&digest=sha256:xyz",
341			"repository=" + repo + "&digest=" + testDigestA + "+",
342			"repository=" + repo + "&tag=alpha&digest=" + testDigestA,
343			"repository=" + repo + "&digest=" + testDigestA + "&tag=alpha",
344			"?repository=" + repo,
345		}
346		for _, raw := range invalid {
347			t.Run("invalid/"+raw, func(t *testing.T) {
348				before := st.readCalls
349				direct, err := input.ParseQuery(raw)
350				if !errors.Is(err, input.ErrInvalidInput) || direct != (service.Query{}) {
351					t.Fatalf("direct ParseQuery(%q) = (%+v, %v), want zero + ErrInvalidInput", raw, direct, err)
352				}
353				assertErrorResponse(t, getArtifacts(t, router, raw),
354					http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
355				if st.readCalls != before {
356					t.Fatalf("invalid query %q reached storage", raw)
357				}
358			})
359		}
360	}
