362	// TestSharedEntryErrorPriorityOverStorageFailure proves on the real wiring
363	// that validation happens wholly inside the store-free input entry: with
364	// the store faulted, every invalid row keeps its 400 and never calls the
365	// store, while legal rows degrade to 503.
366	func TestSharedEntryErrorPriorityOverStorageFailure(t *testing.T) {
367		st := newCaptureStore()
368		router := newCaptureRouter(st)
369		body := registration("registry-demo/prio", testDigestA, "release", true, regRetention, regSizeA)
370		if recorder := postArtifact(t, router, body); recorder.Code != http.StatusCreated {
371			t.Fatalf("seed register status = %d (%s)", recorder.Code, recorder.Body)
372		}
373		st.fault = errors.New("capture backend down")
374	
375		// Invalid registration and query rows: 400, and the store counters do
376		// not move, even though every store method is faulted.
377		regBefore := st.regCalls
378		assertErrorResponse(t, postArtifact(t, router, registrationWithField("size_bytes", "null")),
379			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
380		assertErrorResponse(t, postArtifact(t, router, `{"repository":`),
381			http.StatusBadRequest, codeInvalidInput, msgInvalidReg)
382		assertErrorResponse(t, getArtifacts(t, router, "repository=registry-demo/prio&tag="),
383			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
384		assertErrorResponse(t, getArtifacts(t, router, "repository=x&tag=r&digest="+testDigestA),
385			http.StatusBadRequest, codeInvalidInput, msgInvalidQuery)
386		if st.regCalls != regBefore {
387			t.Fatalf("invalid registration reached a faulted store: %d calls", st.regCalls-regBefore)
388		}
389	
390		// Direct parsing of the same rows rejects without any store existing in
391		// its call path — the input package simply cannot reach one.
392		if _, err := input.ParseRegistration(strings.NewReader(registrationWithField("size_bytes", "null"))); !errors.Is(err, input.ErrInvalidInput) {
393			t.Fatalf("direct invalid registration error = %v", err)
394		}
395		if _, err := input.ParseQuery("repository=x&tag=r&digest=" + testDigestA); !errors.Is(err, input.ErrInvalidInput) {
396			t.Fatalf("direct invalid query error = %v", err)
397		}
398	
399		// Legal rows pass the shared entry and reach the faulted store: 503.
400		assertErrorResponse(t, postArtifact(t, router,
401			registration("registry-demo/prio", testDigestB, "release", true, regRetention, regSizeB)),
402			http.StatusServiceUnavailable, codeStorage, msgStorage)
403		assertErrorResponse(t, getArtifacts(t, router, "repository=registry-demo/prio"),
404			http.StatusServiceUnavailable, codeStorage, msgStorage)
405	}
406	
407	// TestSharedEntryConflictIsServiceLayerNotParse shows parsing a body that
408	// conflicts with committed state still succeeds directly with a non-zero
409	// input; the 409 is the service's decision after parsing.
410	func TestSharedEntryConflictIsServiceLayerNotParse(t *testing.T) {
411		st := newCaptureStore()
412		router := newCaptureRouter(st)
413		first := registration("registry-demo/conf", testDigestA, "release", true, regRetention, regSizeA)
414		if recorder := postArtifact(t, router, first); recorder.Code != http.StatusCreated {
415			t.Fatalf("seed status = %d (%s)", recorder.Code, recorder.Body)
416		}
417	
418		changed := registration("registry-demo/conf", testDigestA, "moved", true, regRetention, regSizeB)
419		direct, err := input.ParseRegistration(strings.NewReader(changed))
420		if err != nil {
421			t.Fatalf("direct parse of a conflicting body rejected at the input boundary: %v", err)
422		}
423		if direct.Tag != "moved" || direct.SizeBytes != regSizeB {
424			t.Fatalf("direct parsed input = %+v", direct)
425		}
